-- Run from the repository root with Lua 5.4: lua5.4 bin/tests/setup_wizard_mix.lua
-- lib/setup_wizard_mix.lua is a port of the configurator's
-- Mixer.buildWizardRules() (src/js/Mixer.js). The configurator has no test of
-- its own for it, so the expected rules below are the real JS builder's
-- output for each set of options, generated by running buildWizardRules()
-- from wingflight-configurator master under Node on 2026-10-14. Each rule is
-- oper,input,output,weight,weightNeg,role. When the JS builder changes,
-- regenerate these and port the change.

local ROOT = "src/wfsuite/"

local failures, checks = 0, 0
local function check(label, ok, detail)
  checks = checks + 1
  if ok then
    print("  ok    " .. label)
  else
    failures = failures + 1
    print("  FAIL  " .. label)
    if detail then print("        " .. tostring(detail)) end
  end
end

local M = assert(loadfile(ROOT .. "lib/setup_wizard_mix.lua"))()

local CASES = {
  {name = "regular", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", motors = 1},
    rules = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,4,27,1000,1000,0"},
  {name = "regularSingleNoMotor", options = {layout = "conventional", ailerons = "single", tailControl = "elevatorOnly", motors = 0},
    rules = "1,1,1,1000,1000,0;1,2,2,1000,1000,0"},
  {name = "regularFlaps2Follow", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 2, flapsFollowAilerons = true, motors = 1},
    rules = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,13,5,1000,1000,0;1,13,6,1000,1000,0;2,1,5,500,500,0;2,1,6,-500,-500,0;2,13,3,0,0,1;1,4,27,1000,1000,0"},
  {name = "regularFlap1", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 1, motors = 1},
    rules = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,13,5,1000,1000,0;2,13,3,0,0,1;1,4,27,1000,1000,0"},
  {name = "flaperons", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 0, motors = 1},
    rules = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;2,13,1,500,500,0;2,13,2,500,500,0;2,13,3,0,0,1;1,4,27,1000,1000,0"},
  {name = "flaperonsNoAilerons", options = {layout = "conventional", ailerons = "none", tailControl = "elevatorRudder", flaps = true, flapServos = 0, motors = 1},
    rules = "1,2,1,1000,1000,0;1,3,2,1000,1000,0;1,4,27,1000,1000,0"},
  {name = "vtail", options = {layout = "conventional", ailerons = "independent", tailControl = "vtail", motors = 1},
    rules = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,3,3,1000,1000,0;2,2,3,1000,1000,0;1,3,4,-1000,-1000,0;2,2,4,1000,1000,0;1,4,27,1000,1000,0"},
  {name = "wingRudder", options = {layout = "flyingWing", wingYaw = "rudder", motors = 2, diffThrustYaw = true},
    rules = "1,2,1,1000,1000,0;2,1,1,1000,1000,0;1,2,2,1000,1000,0;2,1,2,-1000,-1000,0;1,3,3,1000,1000,0;1,4,27,1000,1000,0;1,4,28,1000,1000,0;2,3,27,500,500,2;2,3,28,-500,-500,2"},
  {name = "wingNoYaw", options = {layout = "flyingWing", wingYaw = "none", motors = 1, flaps = true, flapServos = 1},
    rules = "1,2,1,1000,1000,0;2,1,1,1000,1000,0;1,2,2,1000,1000,0;2,1,2,-1000,-1000,0;1,13,3,1000,1000,0;2,13,1,0,0,1;2,13,2,0,0,1;1,4,27,1000,1000,0"},
  {name = "trainer", options = {layout = "conventional", ailerons = "none", tailControl = "elevatorRudder", motors = 1},
    rules = "1,2,1,1000,1000,0;1,3,2,1000,1000,0;1,4,27,1000,1000,0"},
}

for _, case in ipairs(CASES) do
  local got = {}
  for i, r in ipairs(M.buildRules(case.options)) do
    got[i] = table.concat({r.oper, r.input, r.output, r.weight, r.weightNeg, r.role}, ",")
  end
  got = table.concat(got, ";")
  check(case.name .. " matches the configurator", got == case.rules, got)
end

-- The full table: generated rules, then unused slots.
local table32 = M.ruleTable({layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", motors = 1})
check("ruleTable pads to 32 slots", #table32 == 32 and table32[6].oper == 0 and table32[5].output == 27)
check("servosUsed counts servos, not motors", M.servosUsed(table32) == 4)

-- Defaults, as the configurator's setup dialog opens with.
local d = M.defaultOptions(M.typeOf(0))
check("regular airplane defaults", d.ailerons == "independent" and d.tailControl == "elevatorRudder"
  and d.motors == 1 and d.flaps == false)
d = M.defaultOptions(M.typeOf(2))
check("V-tail is fixed", d.tailControl == "vtail")
d = M.defaultOptions(M.typeOf(4))
check("rudder-elevator trainer has no ailerons", d.ailerons == "none" and d.tailControl == "elevatorRudder")
d = M.defaultOptions(M.typeOf(1))
check("flying wing defaults to a rudder", d.layout == "flyingWing" and d.wingYaw == "rudder")

print(string.format("%d checks, %d failed", checks, failures))
os.exit(failures == 0 and 0 or 1)
